problem.script:
def check_pair(expect, ans):
    x_str, y_str = ans
    try:
        x = float(x_str)
        y = float(y_str)
    except (ValueError, TypeError):
        return {
            'overall_message': '<p>Both inputs must be numbers.</p>',
            'input_list': [
                {'ok': False, 'msg': '', 'grade_decimal': 0.0},
                {'ok': False, 'msg': '', 'grade_decimal': 0.0},
            ],
        }

    x_ok = abs(x - EXPECTED_X) < 1e-6
    y_ok = abs(y - EXPECTED_Y) < 1e-6
    y_close = abs(y - EXPECTED_Y) < 0.1

    return {
        'overall_message': '<p>Each input is graded independently.</p>',
        'input_list': [
            {'ok': x_ok,
             'msg': '<p>x is correct.</p>' if x_ok else f'<p>x should be {EXPECTED_X}.</p>',
             'grade_decimal': 1.0 if x_ok else 0.0},
            {'ok': y_ok if y_ok else ('Partial' if y_close else False),
             'msg': '<p>y is correct.</p>' if y_ok else
                    ('<p>y is close — half credit.</p>' if y_close else
                     f'<p>y should be {EXPECTED_Y}.</p>'),
             'grade_decimal': 1.0 if y_ok else (0.5 if y_close else 0.0)},
        ],
    }
